UPDATE tb_notification
   SET closed_yn     = 'Y',
       closed_at     = CURRENT_TIMESTAMP,
       closed_reason = COALESCE(#{reason}, 'DONE')
 WHERE kind      = #{kind}
   AND ref_type  = #{refType}
   AND ref_no    = #{refNo}
   AND closed_yn = 'N'

UPDATE tb_notification SET closed_yn = 'Y', closed_at = CURRENT_TIMESTAMP, closed_reason = 'GONE' WHERE kind = #{kind} AND closed_yn = 'N'
AND ref_no NOT IN
#{no}

