mapper.select:
SELECT n.notification_seq, n.kind, n.role_seq, n.plant_seq, n.ref_type, n.ref_no, n.title, n.body, n.level, n.closed_yn, n.closed_at, n.closed_reason, n.occurred_at, n.created_by, n.created_at, r.role_id, r.role_name, pl.plant_name, EXISTS (SELECT 1 FROM tb_notification_read x WHERE x.notification_seq = n.notification_seq AND x.user_seq = #{userSeq}) AS read_yn, DATE_PART('day', CURRENT_TIMESTAMP - n.occurred_at)::int AS aging_days FROM tb_notification n LEFT JOIN tb_role r ON r.role_seq = n.role_seq LEFT JOIN tb_plant pl ON pl.plant_seq = n.plant_seq
ORDER BY CASE n.level WHEN 'ALERT' THEN 0 WHEN 'WARN' THEN 1 ELSE 2 END, n.occurred_at
LIMIT #{size} OFFSET #{offset}

