             #{o}

                   )

       )
   AND NOT EXISTS (SELECT 1 FROM tb_notification_read x
                    WHERE x.notification_seq = n.notification_seq
                      AND x.user_seq = #{userSeq})

mapper.insert:
INSERT INTO tb_notification_read (notification_seq, user_seq)
SELECT n.notification_seq, #{userSeq}
  FROM tb_notification n
 WHERE n.closed_yn = 'N'
   AND ( n.role_seq IS NULL

         OR EXISTS (SELECT 1 FROM tb_role r2
                     WHERE r2.role_seq = n.role_seq
                       AND r2.role_id IN

             #{rid}

                   )

       )
   AND ( n.plant_seq IS NULL

         OR EXISTS (SELECT 1 FROM tb_plant p2
                     WHERE p2.plant_seq = n.plant_seq
                       AND p2.org_seq IN

             #{o}

                   )

       )
ON CONFLICT (notification_seq, user_seq) DO NOTHING
